#include <vector>
#include <cstddef>
#include <algorithm>
#include <limits>
#include <omp.h>

int edgeCount(std::vector<int> const& A, size_t N) {
    size_t matrixElems;
    if (N != 0 && N > std::numeric_limits<size_t>::max() / N) {
        matrixElems = A.size();  // avoid overflow if N*N would overflow
    } else {
        matrixElems = N * N;
    }

    const size_t total = std::min(A.size(), matrixElems);
    size_t count = 0;

    #pragma omp parallel for reduction(+:count) schedule(static)
    for (size_t idx = 0; idx < total; ++idx) {
        count += (A[idx] != 0) ? size_t{1} : size_t{0};
    }

    if (count > static_cast<size_t>(std::numeric_limits<int>::max())) {
        return std::numeric_limits<int>::max();
    }
    return static_cast<int>(count);
}
